package net.civeira.phylax.feature.observe.observedprobe.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.event.ObservedProbeEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ObservedProbeEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ObservedProbeEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ObservedProbe entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
